package com.linagora.tmail.dav;

/**
 * Answering an invitation missing from the user calendar imports it first. The import is refused when the invitation does
 * not come from a mail (eg an uploaded file), or when the sender of that mail is not aligned with its ORGANIZER.
 */
public class CalendarEventImportRefusedException extends RuntimeException {
    public CalendarEventImportRefusedException(String message) {
        super(message);
    }
}
